#!/usr/bin/env python3
from pathlib import Path
import base64,zlib,subprocess,sys
root=Path(sys.argv[1]).resolve() if len(sys.argv)>1 else Path(__file__).resolve().parent.parent
data=""
p=root/"tools/upgrade_plan_exporter_bundle_tests.py"
p.write_bytes(zlib.decompress(base64.b64decode(data)))
subprocess.run([sys.executable,str(p),str(root)],check=True)
wf=root/".github/workflows/plan2-app.yml"
s=wf.read_text(encoding="utf-8")
old="          python tools/plan2_bundle_source_bootstrap.py . 2>&1 | Tee-Object -Append ci-migrate.txt\n          if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }\n          python tools/plan2_bundle_tests_bootstrap.py . 2>&1 | Tee-Object -Append ci-migrate.txt\n          if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }\n"
new="          python tools/upgrade_plan_exporter_bundle.py . 2>&1 | Tee-Object -Append ci-migrate.txt\n          if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }\n          python tools/upgrade_plan_exporter_bundle_tests.py . 2>&1 | Tee-Object -Append ci-migrate.txt\n          if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }\n"
if old not in s: raise SystemExit("workflow bootstrap anchor missing")
wf.write_text(s.replace(old,new,1),encoding="utf-8",newline="\n")
Path(__file__).unlink()
